/* Parsing macros copied from the producer-pinned zend_API.h. */
#define ZEND_PARSE_PARAMETERS_START_EX(flags, min_num_args, max_num_args)  do {  		const int _flags = (flags);  		uint32_t _min_num_args = (min_num_args);  		uint32_t _max_num_args = (uint32_t) (max_num_args);  		uint32_t _num_args = EX_NUM_ARGS();  		uint32_t _i = 0;  		zval *_real_arg, *_arg = NULL;  		zend_expected_type _expected_type = Z_EXPECTED_LONG;  		char *_error = NULL;  		bool _dummy = 0;  		bool _optional = 0;  		int _error_code = ZPP_ERROR_OK;  		((void)_i);  		((void)_real_arg);  		((void)_arg);  		((void)_expected_type);  		((void)_error);  		((void)_optional);  		((void)_dummy);  		 		do {  			if (UNEXPECTED(_num_args < _min_num_args) ||  			    UNEXPECTED(_num_args > _max_num_args)) {  				if (!(_flags & ZEND_PARSE_PARAMS_QUIET)) {  					zend_wrong_parameters_count_error(_min_num_args, _max_num_args);  				}  				_error_code = ZPP_ERROR_FAILURE;  				break;  			}  			_real_arg = ZEND_CALL_ARG(execute_data, 0);
#define ZEND_PARSE_PARAMETERS_START(min_num_args, max_num_args)   	ZEND_PARSE_PARAMETERS_START_EX(0, min_num_args, max_num_args)
#define ZEND_PARSE_PARAMETERS_END_EX(failure)   			ZEND_ASSERT(_i == _max_num_args || _max_num_args == (uint32_t) -1);  		} while (0);  		if (UNEXPECTED(_error_code != ZPP_ERROR_OK)) {  			if (!(_flags & ZEND_PARSE_PARAMS_QUIET)) {  				zend_wrong_parameter_error(_error_code, _i, _error, _expected_type, _arg);  			}  			failure;  		}  	} while (0)
#define ZEND_PARSE_PARAMETERS_END()   	ZEND_PARSE_PARAMETERS_END_EX(return)
#define Z_PARAM_PROLOGUE(deref, separate)   	++_i;  	ZEND_ASSERT(_i <= _min_num_args || _optional==1);  	ZEND_ASSERT(_i >  _min_num_args || _optional==0);  	if (_optional) {  		if (UNEXPECTED(_i >_num_args)) break;  	}  	_real_arg++;  	_arg = _real_arg;  	if (deref) {  		if (EXPECTED(Z_ISREF_P(_arg))) {  			_arg = Z_REFVAL_P(_arg);  		}  	}  	if (separate) {  		SEPARATE_ZVAL_NOREF(_arg);  	}
#define Z_PARAM_OPTIONAL   	_optional = 1;
#define Z_PARAM_LONG_EX(dest, is_null, check_null, deref)   		Z_PARAM_PROLOGUE(deref, 0);  		if (UNEXPECTED(!zend_parse_arg_long(_arg, &dest, &is_null, check_null, _i))) {  			_expected_type = check_null ? Z_EXPECTED_LONG_OR_NULL : Z_EXPECTED_LONG;  			_error_code = ZPP_ERROR_WRONG_ARG;  			break;  		}
#define Z_PARAM_LONG(dest)   	Z_PARAM_LONG_EX(dest, _dummy, 0, 0)
#define Z_PARAM_VARIADIC_EX(spec, dest, dest_num, post_varargs)  do {  		uint32_t _num_varargs = _num_args - _i - (post_varargs);  		if (EXPECTED(_num_varargs > 0)) {  			dest = _real_arg + 1;  			dest_num = _num_varargs;  			_i += _num_varargs;  			_real_arg += _num_varargs;  		} else {  			dest = NULL;  			dest_num = 0;  		}  		if (UNEXPECTED(ZEND_CALL_INFO(execute_data) & ZEND_CALL_HAS_EXTRA_NAMED_PARAMS)) {  			_error_code = ZPP_ERROR_UNEXPECTED_EXTRA_NAMED;  			break;  		}  	} while (0);
#define Z_PARAM_VARIADIC(spec, dest, dest_num)   	Z_PARAM_VARIADIC_EX(spec, dest, dest_num, 0)
#define Z_PARAM_VARIADIC_WITH_NAMED(dest, dest_num, dest_named)  do {  		uint32_t _num_varargs = _num_args - _i;  		if (EXPECTED(_num_varargs > 0)) {  			dest = _real_arg + 1;  			dest_num = _num_varargs;  		} else {  			dest = NULL;  			dest_num = 0;  		}  		if (ZEND_CALL_INFO(execute_data) & ZEND_CALL_HAS_EXTRA_NAMED_PARAMS) {  			dest_named = execute_data->extra_named_params;  		} else {  			dest_named = NULL;  		}  	} while (0);
